CREATE OR REPLACE FUNCTION public.metrics_scope_match(_unit public.metrics_unit_scope,_scope jsonb) RETURNS boolean LANGUAGE sql STABLE AS $$ SELECT (nullif(_scope->>'building','') IS NULL OR _unit.building_number::text=_scope->>'building') AND (nullif(_scope->>'phase','') IS NULL OR CASE WHEN _scope->>'phase'='unassigned' THEN _unit.phase IS NULL ELSE _unit.phase::text=_scope->>'phase' END) AND (nullif(_scope->>'activity','') IS NULL OR CASE WHEN _scope->>'activity'='unassigned' THEN _unit.activity_id IS NULL ELSE _unit.activity_id::text=_scope->>'activity' END) AND (nullif(_scope->>'unit_type','') IS NULL OR _unit.unit_type=_scope->>'unit_type') AND (nullif(_scope->>'publish_state','') IS NULL OR _unit.publish_state=_scope->>'publish_state') $$;
DO $$ DECLARE d text;BEGIN SELECT pg_get_functiondef('public.metrics_drilldown(text,jsonb,integer,integer)'::regprocedure) INTO d;d:=replace(d,'FUNCTION public.metrics_drilldown(','FUNCTION public._metrics_drilldown_base(');EXECUTE d;END $$;
REVOKE ALL ON FUNCTION public._metrics_drilldown_base(text,jsonb,integer,integer) FROM PUBLIC,anon,authenticated;GRANT EXECUTE ON FUNCTION public._metrics_drilldown_base(text,jsonb,integer,integer) TO service_role;
CREATE OR REPLACE FUNCTION public.metrics_drilldown(_metric text,_scope jsonb DEFAULT '{}',_limit integer DEFAULT 25,_offset integer DEFAULT 0) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE snap jsonb;s jsonb;rows jsonb;total integer;BEGIN IF _metric NOT IN('incomplete','status_review','duplicates','transfers','converted','annual') THEN RETURN public._metrics_drilldown_base(_metric,_scope,_limit,_offset);END IF;snap:=public.metrics_snapshot(_scope);s:=snap->'scope';IF snap->>'audience'='investor' THEN RAISE EXCEPTION 'المستثمر يعرض المجمع فقط';END IF;IF _metric IN('incomplete','status_review','duplicates') AND snap->'quality' IS NULL THEN RAISE EXCEPTION 'غير مسموح بعرض الجودة';END IF;IF _metric='annual' AND snap->'finance' IS NULL THEN RAISE EXCEPTION 'غير مسموح بعرض المالية';END IF;IF _metric='transfers' AND snap->'approvals' IS NULL THEN RAISE EXCEPTION 'غير مسموح بعرض الموافقات';END IF;IF _metric='converted' AND snap->'pipeline' IS NULL THEN RAISE EXCEPTION 'غير مسموح بعرض الفرص';END IF;WITH candidates AS(SELECT u.id,to_jsonb(u) AS row FROM public.metrics_unit_scope u WHERE _metric='incomplete' AND public.metrics_scope_match(u,s) AND (u.building_id IS NULL OR u.activity_id IS NULL OR coalesce(u.area_m2,0)<=0 OR u.unit_type IS NULL) UNION ALL SELECT r.unit_id,to_jsonb(r) FROM public.unit_status_backfill_review r JOIN public.metrics_unit_scope u ON u.id=r.unit_id WHERE _metric='status_review' AND r.resolved_at IS NULL AND public.metrics_scope_match(u,s) UNION ALL SELECT d.id,jsonb_build_object('id',d.id,'status',d.status,'match_reason',d.match_reason) FROM public.duplicate_candidates d WHERE _metric='duplicates' AND d.status='pending' AND s->>'building' IS NULL AND s->>'phase' IS NULL AND s->>'activity' IS NULL AND s->>'unit_type' IS NULL UNION ALL SELECT t.opportunity_id,jsonb_build_object('id',t.opportunity_id,'status',t.status,'created_at',t.created_at) FROM public.transfer_requests t WHERE _metric='transfers' AND t.status='pending' AND public.metrics_opportunity_matches(t.opportunity_id,s) UNION ALL SELECT DISTINCT e.opportunity_id,jsonb_build_object('id',e.opportunity_id) FROM public.metrics_conversion_events e WHERE _metric='converted' AND public.metrics_opportunity_matches(e.opportunity_id,s) AND e.reached_at>=((s->>'from')::date::timestamp AT TIME ZONE 'Asia/Riyadh') AND e.reached_at<(((s->>'to')::date+1)::timestamp AT TIME ZONE 'Asia/Riyadh') UNION ALL SELECT c.id,jsonb_build_object('id',c.id,'contract_no',c.contract_no,'amount_excl_vat',sum(cu.annual_rent_excl_vat),'vat_amount',sum(cu.annual_rent_excl_vat*c.vat_rate/100)) FROM public.contracts c JOIN public.contract_units cu ON cu.contract_id=c.id JOIN public.metrics_unit_scope u ON u.id=cu.unit_id WHERE _metric='annual' AND c.status='active' AND public.metrics_scope_match(u,s) GROUP BY c.id),paged AS(SELECT * FROM candidates ORDER BY id LIMIT least(greatest(_limit,1),500) OFFSET greatest(_offset,0)) SELECT coalesce((SELECT jsonb_agg(row) FROM paged),'[]'),(SELECT count(*) FROM candidates) INTO rows,total;RETURN jsonb_build_object('rows',rows,'count',total,'as_of',snap->'as_of');END $$;
CREATE OR REPLACE FUNCTION public.metrics_admin_verify() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'الأدمن فقط';END IF;RETURN public.metrics_regression_tests();END $$;
REVOKE ALL ON FUNCTION public.metrics_admin_verify() FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.metrics_admin_verify() TO authenticated;
SELECT to_regprocedure('public.metrics_admin_verify()') IS NOT NULL AS verification_ready;